-- M0 simulation ledger. Never used as a production custody ledger.
CREATE TABLE platform_accounts(account_id TEXT PRIMARY KEY REFERENCES accounts(id),created_at INTEGER NOT NULL);
INSERT INTO platform_accounts SELECT id,created_at FROM accounts;
CREATE TRIGGER platform_account_created AFTER INSERT ON accounts BEGIN INSERT INTO platform_accounts VALUES(NEW.id,NEW.created_at); END;
CREATE TABLE asset_registry(id TEXT PRIMARY KEY,network TEXT NOT NULL,contract_address TEXT NOT NULL,decimals INTEGER NOT NULL CHECK(decimals BETWEEN 0 AND 18),kind TEXT NOT NULL CHECK(kind IN('stable','fun')),metadata TEXT NOT NULL,flags TEXT NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(network,contract_address));
CREATE TABLE asset_balances(owner TEXT NOT NULL,asset_id TEXT NOT NULL REFERENCES asset_registry(id),bucket TEXT NOT NULL,units TEXT NOT NULL,PRIMARY KEY(owner,asset_id,bucket));
CREATE TABLE asset_journals(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES asset_registry(id),reference TEXT NOT NULL,kind TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(asset_id,reference));
CREATE TABLE asset_lines(journal_id TEXT NOT NULL REFERENCES asset_journals(id),ordinal INTEGER NOT NULL,owner TEXT NOT NULL,bucket TEXT NOT NULL,units TEXT NOT NULL,PRIMARY KEY(journal_id,ordinal));
CREATE TABLE asset_requests(account_id TEXT NOT NULL REFERENCES accounts(id),request_id TEXT NOT NULL,operation TEXT NOT NULL,digest TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(account_id,request_id));
CREATE TABLE wallet_bindings(account_id TEXT PRIMARY KEY REFERENCES accounts(id),address TEXT,version INTEGER NOT NULL DEFAULT 0,last_address TEXT,pending_address TEXT,pending_until INTEGER,protection_until INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE wallet_binding_history(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),address TEXT,version INTEGER NOT NULL,action TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(account_id,version));
CREATE TABLE wallet_challenges(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),address TEXT NOT NULL,message TEXT NOT NULL,version INTEGER NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE wallet_deletions(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),address TEXT,version INTEGER NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL,completed_at INTEGER);
CREATE TABLE asset_deposits(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),asset_id TEXT NOT NULL REFERENCES asset_registry(id),event_key TEXT NOT NULL UNIQUE,units TEXT NOT NULL,block_hash TEXT NOT NULL,confirmations INTEGER NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE asset_withdrawals(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),asset_id TEXT NOT NULL REFERENCES asset_registry(id),units TEXT NOT NULL,net_units TEXT NOT NULL,fee_asset TEXT NOT NULL,fee_units TEXT NOT NULL,address TEXT NOT NULL,binding_version INTEGER NOT NULL,credential_version INTEGER,status TEXT NOT NULL,quote_expires INTEGER NOT NULL,fee_version TEXT NOT NULL,nonce TEXT,expected_hash TEXT,signed_payload TEXT,reason TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE asset_gifts(id TEXT PRIMARY KEY,sender_id TEXT NOT NULL REFERENCES accounts(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),asset_id TEXT NOT NULL REFERENCES asset_registry(id),kind TEXT NOT NULL,distribution TEXT NOT NULL,total_units TEXT NOT NULL,remaining_units TEXT NOT NULL,shares INTEGER NOT NULL,remaining_shares INTEGER NOT NULL,status TEXT NOT NULL,recipient_id TEXT REFERENCES accounts(id),bounty_id TEXT,note TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE asset_gift_eligibility(gift_id TEXT NOT NULL REFERENCES asset_gifts(id),account_id TEXT NOT NULL REFERENCES accounts(id),joined_at INTEGER NOT NULL,history_start_id INTEGER NOT NULL,PRIMARY KEY(gift_id,account_id));
CREATE TABLE asset_claims(id TEXT PRIMARY KEY,gift_id TEXT NOT NULL REFERENCES asset_gifts(id),account_id TEXT NOT NULL REFERENCES accounts(id),units TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(gift_id,account_id));
CREATE TABLE asset_outbox(id TEXT PRIMARY KEY,gift_id TEXT NOT NULL UNIQUE REFERENCES asset_gifts(id),conversation_id TEXT NOT NULL,payload TEXT NOT NULL,delivered_at INTEGER,attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE asset_risk(account_id TEXT PRIMARY KEY REFERENCES accounts(id),reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE asset_incidents(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL,account_id TEXT,reference TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(reference,reason));

CREATE TABLE asset_gift_messages(message_id INTEGER PRIMARY KEY REFERENCES messages(id),gift_id TEXT NOT NULL UNIQUE REFERENCES asset_gifts(id));
